/* @lc app=leetcode id=1034 lang=kotlin */ class Solution { fun nb(g: Array<IntArray>, p: IntArray) = listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) }.filter { it[0] in g.indices && it[1] in g[0].indices } fun mark(s: Array<BooleanArray>, p: IntArray) { s[p[0]][p[1]] = true } fun colorBorder(grid: Array<IntArray>, row: Int, col: Int, color: Int): Array<IntArray> = grid[row][col].let { o -> Array(grid.size) { BooleanArray(grid[0].size) }.also { it[row][col] = true }.let { seen -> java.util.ArrayDeque(listOf(intArrayOf(row, col))).let { q -> generateSequence { q.poll() }.onEach { p -> nb(grid, p).filter { !seen[it[0]][it[1]] && grid[it[0]][it[1]] == o }.forEach { x -> mark(seen, x).also { q.add(x) } } }.toList() } }.let { comp -> comp.filter { p -> nb(grid, p).size < 4 || nb(grid, p).any { grid[it[0]][it[1]] != o } }.forEach { grid[it[0]][it[1]] = color } }.let { grid } } }